14	/**
15	 * 发电车域幂等存取：requestId 唯一键，首次成功时同事务写入结构化指纹与冻结结果JSON；
16	 * 同键同参重放首次结果，同键异参抛409，业务失败回滚不占键。
17	 */
18	@Component
19	public class GenIdempotency {
20	
21	    private final JdbcTemplate jdbc;
22	    private final AppClock clock;
23	    private final ObjectMapper objectMapper;
24	
25	    public GenIdempotency(JdbcTemplate jdbc, AppClock clock, ObjectMapper objectMapper) {
26	        this.jdbc = jdbc;
27	        this.clock = clock;
28	        this.objectMapper = objectMapper;
29	    }
30	
31	    /**
32	     * 按 requestId 查询首次冻结结果；不存在返回空，指纹不一致抛409。
33	     */
34	    public <T> Optional<T> findReplay(String requestId, String fingerprint, Class<T> type) {
35	        List<String[]> rows = jdbc.query(
36	                "SELECT fingerprint, outcome FROM gen_idempotency WHERE request_id = ?",
37	                (rs, rowNum) -> new String[] {rs.getString(1), rs.getString(2)}, requestId);
38	        if (rows.isEmpty()) {
39	            return Optional.empty();
40	        }
41	        String[] row = rows.get(0);
42	        if (!row[0].equals(fingerprint)) {
43	            throw new ConflictException("同键异参幂等冲突: requestId=" + requestId);
44	        }
45	        try {
46	            return Optional.of(objectMapper.readValue(row[1], type));
47	        } catch (Exception e) {
48	            throw new IllegalStateException("幂等结果反序列化失败: requestId=" + requestId, e);
49	        }
50	    }
51	
52	    /**
53	     * 同事务记录首次冻结结果。
54	     */
55	    public void record(String requestId, String fingerprint, String op, long entityId, Object outcome) {
56	        final String json;
57	        try {
58	            json = objectMapper.writeValueAsString(outcome);
59	        } catch (Exception e) {
60	            throw new IllegalStateException("幂等结果序列化失败: requestId=" + requestId, e);
61	        }
62	        jdbc.update("INSERT INTO gen_idempotency (request_id, fingerprint, op, entity_id, outcome, created_at)"
63	                + " VALUES (?,?,?,?,?,?)",
64	                requestId, fingerprint, op, entityId, json, Timestamp.valueOf(clock.now()));
65	    }
66	}
