4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.HexFormat;
8	import java.util.List;
9	
10	/**
11	 * 幂等指纹工具：对 requestId 与全部业务字段的拼接计算 SHA-256。
12	 */
13	public final class Fingerprints {
14	
15	    private Fingerprints() {
16	    }
17	
18	    /**
19	     * 计算指纹。字段按传入顺序以竖线拼接，空值按空串处理。
20	     */
21	    public static String of(Object... fields) {
22	        StringBuilder sb = new StringBuilder();
23	        for (Object field : fields) {
24	            sb.append(field == null ? "" : field.toString()).append('|');
25	        }
26	        return sha256(sb.toString());
27	    }
28	
29	    /**
30	     * 计算结构化指纹：每个字段长度前缀编码（类型标记+字节长度+原文），集合递归编码并携带元素数。
31	     * 字段值本身包含分隔符时仍可无歧义区分，如 ["a|","b"] 与 ["a","|b"] 指纹不同。
32	     */
33	    public static String structured(Object... fields) {
34	        StringBuilder sb = new StringBuilder();
35	        for (Object field : fields) {
36	            encode(sb, field);
37	        }
38	        return sha256(sb.toString());
39	    }
40	
41	    private static void encode(StringBuilder sb, Object field) {
42	        if (field == null) {
43	            sb.append("N;");
44	        } else if (field instanceof Iterable<?> items) {
45	            List<Object> list = new ArrayList<>();
46	            items.forEach(list::add);
47	            sb.append('L').append(list.size()).append(';');
48	            for (Object item : list) {
49	                encode(sb, item);
50	            }
51	            sb.append("E;");
52	        } else {
53	            String s = field.toString();
54	            sb.append('S').append(s.getBytes(StandardCharsets.UTF_8).length).append(';').append(s).append(';');
55	        }
56	    }
57	
58	    private static String sha256(String text) {
59	        try {
60	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
61	            return HexFormat.of().formatHex(digest.digest(text.getBytes(StandardCharsets.UTF_8)));
62	        } catch (NoSuchAlgorithmException e) {
63	            throw new IllegalStateException("SHA-256 不可用", e);
64	        }
65	    }
66	}
