package com.example.starter.web.dto;

import java.time.Instant;
import java.util.List;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 热备接替创建请求。仅SUPPLYING调度单可申请；expectedVersion 为原调度单当前版本；
 * 引用一辆正在供电的旧车与1至3辆未占用新车，新车同馈线且容量之和不少于旧车容量（恰等合法）。
 *
 * @param requestId       幂等请求号
 * @param dispatchId      原SUPPLYING调度单ID
 * @param expectedVersion 期望的原调度单版本号
 * @param oldTruckId      被接替的供电旧车ID
 * @param newTruckIds     热备新车ID列表，1至3辆，不可重复
 * @param createdAt       UTC精确申请时刻
 */
public record CreateReplacementRequest(
        @NotBlank String requestId,
        @NotNull Long dispatchId,
        @NotNull Long expectedVersion,
        @NotNull Long oldTruckId,
        @NotEmpty @Size(max = 3) List<@NotNull Long> newTruckIds,
        @NotNull Instant createdAt) {
}

package com.example.starter.web.dto;

import java.time.LocalDateTime;

/**
 * 接替单内热备新车视图。
 *
 * @param truckId    车辆ID
 * @param capacityKw 容量，单位kW
 * @param arrivedAt  到场时刻，空表示未到场
 */
public record ReplacementTruckView(long truckId, int capacityKw, LocalDateTime arrivedAt) {
}

package com.example.starter.web.dto;

import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 热备新车到场登记请求。expectedVersion 为接替单当前版本；arrivedAt 为UTC精确到场时刻。
 *
 * @param requestId       幂等请求号
 * @param expectedVersion 期望的接替单版本号
 * @param truckId         到场的热备新车ID
 * @param arrivedAt       UTC精确到场时刻
 */
public record ReplacementArrivalRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotNull Long truckId,
        @NotNull Instant arrivedAt) {
}

package com.example.starter.web.dto;

import java.time.LocalDateTime;

/**
 * 热备新车到场登记响应。outcome：ARRIVED已记录/ALL_ARRIVED新车全部到齐（待双人确认切换）。
 *
 * @param replacementId 接替单ID
 * @param truckId       车辆ID
 * @param outcome       到场结果
 * @param status        接替单当前状态
 * @param version       接替单当前版本号
 * @param arrivedAt     到场时刻（本地时间）
 */
public record ReplacementArrivalResponse(long replacementId, long truckId, String outcome, String status,
        int version, LocalDateTime arrivedAt) {
}

package com.example.starter.web.dto;

import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 切换确认请求。新车到齐后由两个不同合成操作员确认才切换；expectedVersion 为接替单当前版本。
 *
 * @param requestId       幂等请求号
 * @param expectedVersion 期望的接替单版本号
 * @param operator        合成操作员
 * @param confirmedAt     UTC精确确认时刻
 */
public record SwitchConfirmRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotBlank String operator,
        @NotNull Instant confirmedAt) {
}

package com.example.starter.web.dto;

import java.time.LocalDateTime;

/**
 * 切换确认响应。switched=false 表示已记录确认、尚待第二人；switched=true 表示双人确认齐全、
 * 供电组合已原子替换，旧车释放、新车占用转移并留前后容量证据。
 *
 * @param replacementId 接替单ID
 * @param status        接替单当前状态
 * @param version       接替单当前版本号
 * @param switched      本次确认后是否已完成切换
 * @param oldCapacityKw 切换前旧车容量证据，单位kW
 * @param newCapacityKw 切换后新车容量合计证据，单位kW，空表示未切换
 * @param switchedAt    切换完成时刻，空表示未切换
 */
public record SwitchConfirmResponse(long replacementId, String status, int version, boolean switched,
        int oldCapacityKw, Integer newCapacityKw, LocalDateTime switchedAt) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 热备接替撤回请求。仅未切换（STANDBY）可撤回；释放全部新车预占而保留旧车供电。
 *
 * @param requestId       幂等请求号
 * @param expectedVersion 期望的接替单版本号
 */
public record WithdrawReplacementRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion) {
}

package com.example.starter.web.dto;

import java.util.List;

/**
 * 热备接替撤回响应：全部新车预占释放，旧车继续供电，旧到场与供电证据不覆盖。
 *
 * @param replacementId    接替单ID
 * @param status           接替单当前状态（WITHDRAWN）
 * @param version          接替单当前版本号
 * @param releasedTruckIds 已释放预占的热备新车
 */
public record WithdrawReplacementResponse(long replacementId, String status, int version,
        List<Long> releasedTruckIds) {
}

